#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk.Web #:package Microsoft.CodeAnalysis.CSharp@4.7.0 #:package Microsoft.CodeAnalysis.Analyzers@3.3.4 #:package Roslynator.Analyzers@4.2.0 #:property LangVersion=preview #:property TargetFramework=net11.0 #:property Nullable=enable #:property ImplicitUsings=enable  using System.Text; using Microsoft.CodeAnalysis; using Microsoft.CodeAnalysis.Text; using Microsoft.CodeAnalysis.Formatting;  [Generator] public class AdvancedDtoGenerator : IIncrementalGenerator {     public void Initialize(IncrementalGeneratorInitializationContext context)     {         // 1. 多文件生成策略         var dtoClasses = context.SyntaxProvider             .CreateSyntaxProvider(                 predicate: (node, _) => IsDtoCandidate(node),                 transform: (ctx, _) => GetDtoInfo(ctx))             .Where(info => info != null)             .Collect();                  context.RegisterSourceOutput(dtoClasses, (ctx, infos) =>          {             foreach (var info in infos)             {                 // 2. 代码格式化控制                 var formattedSource = FormatSourceCode(GenerateDtoSource(info));                 ctx.AddSource($"{info.Name}Dto.g.cs", SourceText.From(formattedSource, Encoding.UTF8));                                  // 生成验证类                 var validatorSource = FormatSourceCode(GenerateValidatorSource(info));                 ctx.AddSource($"{info.Name}Validator.g.cs", SourceText.From(validatorSource, Encoding.UTF8));             }         });     }      private bool IsDtoCandidate(SyntaxNode node) =>          node is ClassDeclarationSyntax classDecl &&          classDecl.AttributeLists.Any(a => a.Attributes.Any(at => at.Name.ToString().Contains("Dto")));      private DtoInfo GetDtoInfo(GeneratorSyntaxContext context)     {         var model = context.SemanticModel.GetDeclaredSymbol(context.Node);         return model != null ? new DtoInfo         {             Name = model.Name,             Namespace = model.ContainingNamespace.ToDisplayString(),             Properties = model.GetMembers()                 .OfType<IPropertySymbol>()                 .Select(p => new PropertyInfo                 {                     Name = p.Name,                     Type = p.Type.ToDisplayString(),                     IsNullable = p.NullableAnnotation == NullableAnnotation.Annotated                 })                 .ToList()         } : null;     }      private string GenerateDtoSource(DtoInfo info)     {         var sb = new StringBuilder();         sb.AppendLine("// <auto-generated/>");         sb.AppendLine("using System;");         sb.AppendLine("using System.ComponentModel.DataAnnotations;");         sb.AppendLine();         sb.AppendLine($"namespace {info.Namespace}");         sb.AppendLine("{");         sb.AppendLine($"    public partial class {info.Name}Dto");         sb.AppendLine("    {");                  foreach (var prop in info.Properties)         {             sb.AppendLine($"        public {prop.Type}{(prop.IsNullable ? "?" : "")} {prop.Name} {{ get; set; }}");         }                  sb.AppendLine("    }");         sb.AppendLine("}");         return sb.ToString();     }      // 3. 生成代码验证机制     private string GenerateValidatorSource(DtoInfo info)     {         var sb = new StringBuilder();         sb.AppendLine("// <auto-generated/>");         sb.AppendLine("using FluentValidation;");         sb.AppendLine();         sb.AppendLine($"namespace {info.Namespace}");         sb.AppendLine("{");         sb.AppendLine($"    public class {info.Name}Validator : AbstractValidator<{info.Name}Dto>");         sb.AppendLine("    {");         sb.AppendLine($"        public {info.Name}Validator()");         sb.AppendLine("        {");                  foreach (var prop in info.Properties)         {             if (!prop.IsNullable)                 sb.AppendLine($"            RuleFor(x => x.{prop.Name}).NotNull();");                          if (prop.Type == "string")                 sb.AppendLine($"            RuleFor(x => x.{prop.Name}).NotEmpty();");         }                  sb.AppendLine("        }");         sb.AppendLine("    }");         sb.AppendLine("}");         return sb.ToString();     }      private string FormatSourceCode(string source)     {         var workspace = new AdhocWorkspace();         var project = workspace.AddProject("TempProject", LanguageNames.CSharp);         var document = workspace.AddDocument(project.Id, "Temp.cs", SourceText.From(source));                  var formattedDocument = Formatter.FormatAsync(             document,              workspace.Options.WithChangedOption(                 FormattingOptions.NewLine, LanguageNames.CSharp, "\n"))             .GetAwaiter().GetResult();                  return formattedDocument.GetTextAsync().GetAwaiter().GetResult().ToString();     } }  public class DtoInfo {     public string Name { get; set; }     public string Namespace { get; set; }     public List<PropertyInfo> Properties { get; set; } }  public class PropertyInfo {     public string Name { get; set; }     public string Type { get; set; }     public bool IsNullable { get; set; } }
